	return (
		<Icon {...props}>
			<path d="M5.2 15.5c.9-1 1.3-2.2 1.3-3.6V10a5.5 5.5 0 0 1 11 0v1.9c0 1.4.4 2.6 1.3 3.6.5.6.1 1.5-.7 1.5H5.9c-.8 0-1.2-.9-.7-1.5Z" />
			<path d="M10 20a2.2 2.2 0 0 0 4 0" />
		</Icon>
	);
}

