	return (
		<Icon {...props}>
			<path d="M12 21a9 9 0 1 1 9-9c0 2.2-1.8 3.5-3.8 3.5h-1.7c-1 0-1.8.8-1.8 1.8 0 .5.2.9.5 1.2.3.3.5.7.5 1.2 0 .7-.6 1.3-1.3 1.3H12Z" />
